with tarfile.open(fileobj=io.BytesIO(archive),mode='r:gz') as tar:
    entries=tar.getmembers()
    require(len(entries)==103 and len({x.name for x in entries})==103 and {x.name for x in entries}==set(members),'archive member set differs')
    for member in entries:
        require(member.isfile() and not member.issym() and not member.islnk(),'archive contains non-regular member')
        target=deployment/member.name
        require(not pathlib.PurePosixPath(member.name).is_absolute() and all(x not in ('','.','..') for x in member.name.split('/')),'unsafe archive path')
        target.parent.mkdir(parents=True,exist_ok=True)
        raw=tar.extractfile(member).read()
        expected=members[member.name]
        require(len(raw)==expected['bytes'] and hashlib.sha256(raw).hexdigest()==expected['sha256'],'archive member hash differs')
        save(target,raw)
require(len(list(deployment.rglob('*')))>0,'empty deployment')
